INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('POLIZZA_COMPAGNIA', '"Assicurazioni Esempio Spa"', 'La compagnia della polizza professionale: va scritta in ogni preventivo (legge 124/2017).');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('POLIZZA_NUMERO', '"RC-0000-PROVA"', 'Il numero della polizza professionale.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('POLIZZA_MASSIMALE', '"1.000.000 euro"', 'Il massimale della polizza professionale, come va scritto nel preventivo.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('TITOLI', '"Perito industriale iscritto al Collegio dei periti industriali (dato di esempio)"', 'Iscrizione al collegio, titoli e specializzazioni: vanno scritti in ogni preventivo.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('IVA', '22', 'L''IVA in percentuale. Ogni preventivo tiene quella del giorno in cui nasce.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('EPPI_INTEGRATIVO', '5', 'Il contributo integrativo EPPI in percentuale: entra nella base dell''IVA. Da confermare col commercialista.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('RITENUTA', '20', 'La ritenuta d''acconto in percentuale. Si userà con le fatture.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('PREVENTIVO_VALIDITA_GIORNI', '30', 'Per quanti giorni vale un preventivo, se non si scrive la scadenza.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('PREVENTIVO_CONDIZIONI', '"Il compenso è quello delle voci, a corpo o a ore come scritto. Sono escluse le spese non elencate. I pagamenti seguono le scadenze indicate. Il preventivo vale fino alla data di scadenza."', 'Le condizioni che ogni preventivo nuovo propone. Si cambiano preventivo per preventivo.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('APPROVAZIONE', '"collaboratori"', 'Chi deve far approvare ore, rapportini, spese e trasferte: collaboratori (di base), tutti o nessuno.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('ACI_ANNO', '2026', 'L''anno delle tabelle ACI dei rimborsi km dei veicoli. Dall''anno nuovo la Dashboard chiede di aggiornarle.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('INDENNITA_TRASFERTA', '""', 'L''indennità proposta per ogni giorno di trasferta, in euro. Vuota: nessuna.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('ORE_GIORNALIERE', '8', 'Le ore di una giornata normale. Più di queste 4 in un giorno è un''anomalia da guardare prima di approvare.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('REGIME_FISCALE', '"RF01"', 'Il regime fiscale dello studio: RF01 ordinario, RF19 forfettario. Da confermare col commercialista.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('TIPO_DOCUMENTO', '"TD01"', 'Il tipo di documento delle fatture: TD01 fattura o TD06 parcella. Da chiedere al commercialista.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('RITENUTA_TIPO', '"RT01"', 'Il codice della ritenuta nella fattura elettronica (RT01: persone fisiche).');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('RITENUTA_CAUSALE', '"A"', 'La causale del pagamento per la ritenuta (A: lavoro autonomo abituale, modello CU).');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('EPPI_TIPO_CASSA', '"TC17"', 'Il codice della cassa previdenziale nella fattura elettronica (TC17: EPPI).');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('BOLLO_SOGLIA', '77.47', 'Il bollo scatta quando la parte senza IVA della fattura supera questa cifra.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('BOLLO_IMPORTO', '2', 'L''imposta di bollo delle fatture elettroniche, in euro.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('BOLLO_RIVALSA', 'true', 'Il bollo si riaddebita al cliente (una riga senza IVA nella fattura).');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('GIORNI_PAGAMENTO', '30', 'Quanti giorni ha il cliente per pagare: scadenza = data della fattura + giorni.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('PAGAMENTO_FINE_MESE', 'false', 'La scadenza va alla fine del mese (dopo i giorni di pagamento).');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('MODALITA_PAGAMENTO', '"MP05"', 'Come si fa pagare lo studio: MP05 bonifico.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('PASSAGGIO_USCITE', '["prospetto","xml"]', 'Cosa si passa al programma delle fatture: il prospetto da copiare e l''XML da completare.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('SOGLIA_CASSA', '3000', 'Sotto questo saldo previsto il giorno dello scadenziario e'' rosso.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('REGOLE_FISCALI_CONFERMATE', 'null', 'Quando e chi ha confermato le regole fiscali (lo segna il titolare). Cambiare una regola toglie la conferma.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('CODICE_FISCALE', '"00000000000"', 'Il codice fiscale dello studio, per le fatture.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('STUDIO_CAP', '"36016"', 'Il CAP della sede dello studio, per le fatture.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('STUDIO_COMUNE', '"Thiene"', 'Il comune della sede dello studio, per le fatture.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('STUDIO_PROVINCIA', '"VI"', 'La provincia della sede dello studio (due lettere), per le fatture.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('ALBO', '"Periti industriali"', 'L''albo professionale, per esempio "Periti industriali".');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('ALBO_PROVINCIA', '"VI"', 'La provincia dell''albo (due lettere).');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('ALBO_NUMERO', '"000"', 'Il numero di iscrizione all''albo.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('ALBO_DATA', '""', 'La data di iscrizione all''albo.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('EURO_KM', '0.76', 'Rimborso chilometrico, se la commessa non ne ha uno suo. Da controllare ogni gennaio sulla tabella ACI dell''auto qui sotto.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('AUTO', '"Volvo XC40"', 'L''auto su cui si calcola il rimborso ACI.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('COSTO_ORARIO', '15', 'Quanto costa a te un''ora di lavoro. Serve solo a calcolare il margine delle commesse.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('TICKET_ATTIVO', '"NO"', 'SI per mostrare il campo ticket nel rapportino.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('TECNICO', '"Manuel Gasparotto"', 'Il nome che compare come compilatore.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('RAGIONE_SOCIALE', '"Studio Tecnico GM"', 'Intestazione dei PDF.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('INDIRIZZO', '"Via dell''Esempio 1, 36016 Thiene (VI)"', 'Intestazione dei PDF.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('PARTITA_IVA', '"00000000000"', 'Intestazione dei PDF.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('EMAIL', '"studio@example.com"', 'Intestazione dei PDF.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('TELEFONO', '""', 'Intestazione dei PDF.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('PEC', '""', 'Intestazione dei PDF.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('FIRMA_TECNICO', '""', 'La firma del compilatore: si mette da sola su ogni rapportino. La carica il programma.');
INSERT INTO impostazioni (chiave, valore, descrizione) VALUES ('EMAIL_AVVISI', '""', 'Chi riceve gli avvisi di sicurezza oltre al titolare. Piu'' indirizzi separati da virgola.');
